function dgNew(){return {nodes:[],edges:[]};}
function dgNode(g,id,label,kind){g.nodes.push({id:id,label:label,kind:kind||'box'});return g;}
function dgEdge(g,from,to,label){g.edges.push({from:from,to:to,label:label||''});return g;}
function dgLayout(g){var pos={};g.nodes.forEach(function(n,i){pos[n.id]={x:20+i*140,y:60};});return pos;}
function dgSvg(g){var pos=dgLayout(g);var parts=['<svg xmlns="http://www.w3.org/2000/svg" width="800" height="200">'];
g.edges.forEach(function(e){var a=pos[e.from],b=pos[e.to];if(a&&b)parts.push('<line x1="'+(a.x+100)+'" y1="'+a.y+'" x2="'+b.x+'" y2="'+b.y+'" stroke="black"/>');});
g.nodes.forEach(function(n){var p=pos[n.id];var shape=n.kind==='diamond'?'<polygon points="'+p.x+','+(p.y-30)+' '+(p.x+100)+','+p.y+' '+p.x+','+(p.y+30)+' '+(p.x-100)+','+p.y+'" fill="white" stroke="black"/>':'<rect x="'+p.x+'" y="'+(p.y-25)+'" width="120" height="50" fill="white" stroke="black"/>';
parts.push(shape+'<text x="'+(p.x+60)+'" y="'+(p.y+5)+'" text-anchor="middle">'+n.label+'</text>');});
parts.push('</svg>');return parts.join('');}
